<template><div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-logo"><i></i><i></i><i></i></span><span class="brand-name">Smart <b>CRM</b><small>Customer workspace</small></span></div><p class="nav-label">MAIN MENU</p><nav><RouterLink v-for="item in items" :key="item.path" :to="item.path"><span class="nav-icon">{{ item.icon }}</span><span>{{ item.name }}</span></RouterLink></nav><div class="sidebar-footer"><div class="user-box"><div class="avatar">{{ initials }}</div><div class="user-text"><strong>{{ user?.full_name || 'User' }}</strong><small>{{ user?.role || 'Member' }}</small></div><button class="logout" title="Logout" @click="logout">↗</button></div><div class="secure-line"><span>●</span> Secure workspace</div></div></aside><main class="content"><header><div><span class="eyebrow">SMART CRM <b>/</b> {{ $route.name }}</span><h2>{{ $route.name }}</h2><p class="header-subtitle">Stay focused. Move relationships forward.</p></div><div class="status-pill"><span></span> Workspace online</div></header><RouterView /></main></div></template>
<script setup>
import { ref, computed, onMounted } from 'vue'; import { useRouter } from 'vue-router'; import { getMe, token } from '../api'
const router = useRouter(), user = ref(null), items = [{name:'Dashboard',path:'/',icon:'⌂'},{name:'Customers',path:'/customers',icon:'♙'},{name:'Contacts',path:'/contacts',icon:'◎'},{name:'Deals',path:'/deals',icon:'◇'},{name:'Activities',path:'/activities',icon:'◷'}]; const initials = computed(() => (user.value?.full_name || 'U').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()); onMounted(async () => { try { user.value = await getMe() } catch { token.clear(); router.push('/login') } }); function logout(){ token.clear(); router.push('/login') }
</script>
